import time
import sys
import signal
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PINS = [2, 3, 4]
INTERVAL_SECONDS = 60

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            try:
                dev = OutputDevice(pin)
                devices.append(dev)
            except GPIOZeroError as exc:
                print(f"Error: failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
                for d in devices:
                    d.close()
                sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error during GPIO setup: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            for dev in devices:
                try:
                    dev.on()
                    print(f"GPIO {dev.pin.number} -> HIGH")
                except DeviceClosed:
                    print(f"Warning: device on GPIO {dev.pin.number} is closed.", file=sys.stderr)
                except GPIOZeroError as exc:
                    print(f"Error: failed to set GPIO {dev.pin.number} HIGH: {exc}", file=sys.stderr)
            for dev in devices:
                try:
                    dev.off()
                    print(f"GPIO {dev.pin.number} -> LOW")
                except DeviceClosed:
                    print(f"Warning: device on GPIO {dev.pin.number} is closed.", file=sys.stderr)
                except GPIOZeroError as exc:
                    print(f"Error: failed to set GPIO {dev.pin.number} LOW: {exc}", file=sys.stderr)
            for _ in range(INTERVAL_SECONDS):
                if not _running:
                    break
                time.sleep(1)
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

