import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
WHO_AM_I = 0x75
WHO_AM_I_EXPECTED = 0x68

running = True


def _handle_signal(signum, frame):
    global running
    running = False


def _write_reg(bus, reg, value):
    bus.write_byte_data(MPU6050_ADDR, reg, value)


def _read_reg(bus, reg):
    return bus.read_byte_data(MPU6050_ADDR, reg)


def _read_word(bus, reg):
    low = bus.read_byte_data(MPU6050_ADDR, reg)
    high = bus.read_byte_data(MPU6050_ADDR, reg + 1)
    return (high << 8) | low


def _init_device(bus):
    who = _read_reg(bus, WHO_AM_I)
    if who != WHO_AM_I_EXPECTED:
        raise RuntimeError(f"WHO_AM_I mismatch: got 0x{who:02X}, expected 0x{WHO_AM_I_EXPECTED:02X}")
    _write_reg(bus, PWR_MGMT_1, 0x00)


def main():
    global running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = SMBus(1)
        _init_device(bus)
        print("MPU6050 initialized at address 0x68")

        while running:
            try:
                accel_x = _read_word(bus, 0x3B)
                accel_y = _read_word(bus, 0x3D)
                accel_z = _read_word(bus, 0x3F)
                print(f"X={accel_x} Y={accel_y} Z={accel_z}")
            except OSError as e:
                print(f"I2C read error: {e}", file=sys.stderr)
                break
            time.sleep(0.01)

    except OSError as e:
        print(f"Failed to open I2C bus or communicate with MPU6050: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass
        print("Program terminated.")


if __name__ == "__main__":
    main()

