                    continue
            time.sleep(0.1)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        for pwm in pwm_devices:
            try:
                pwm.value = 0.0
                pwm.close()
            except Exception:
                pass
        print("GPIO cleanup complete.")

