import serial
import sys
import signal

SERIAL_PORT = '/dev/serial0'  # Raspberry Pi primary UART (GPIO 14/15)
BAUD_RATE = 9600
TIMEOUT_S = 1.0
MAX_RETRIES = 3

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def open_serial_port():
    try:
        return serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT_S,
        )
    except serial.SerialException as exc:
        print(f"Error opening serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"OS error opening serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None

def read_sensor_data(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None
    return raw.decode('ascii', errors='replace').strip()

def process_data(data):
    if not data:
        return False
    print(f"Sensor reading: {data}")
    return True

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = open_serial_port()
    if ser is None:
        sys.exit(1)

    try:
        for attempt in range(1, MAX_RETRIES + 1):
            if not _running:
                print("Interrupted by user.", file=sys.stderr)
                break
            data = read_sensor_data(ser)
            if data:
                if not process_data(data):
                    print("Invalid data received; skipping.", file=sys.stderr)
                else:
                    break
            elif attempt < MAX_RETRIES:
                print(f"Read failed (attempt {attempt}/{MAX_RETRIES}); retrying...", file=sys.stderr)
    finally:
        try:
            ser.close()
        except Exception:
            pass

if __name__ == '__main__':
    main()

import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

TRIGGER_PIN = 17
ECHO_PIN = 22
CYCLES = 5
DELAY_SECONDS = 50

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = DistanceSensor(echo=ECHO_PIN, trigger=TRIGGER_PIN, max_distance=4.0)
    except GPIOZeroError as exc:
        print(f"Failed to initialize HC-SR04 on trigger=GPIO{TRIGGER_PIN}, echo=GPIO{ECHO_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(1, CYCLES + 1):
            if not _running:
                print("Interrupted by signal; exiting early.", file=sys.stderr)
                break

            try:
                distance_m = sensor.distance
            except DeviceClosed:
                print("Device closed unexpectedly; exiting.", file=sys.stderr)
                break
            except GPIOZeroError as exc:
                print(f"Read error on cycle {i}: {exc}", file=sys.stderr)
                break

            if distance_m is None:
                print(f"Cycle {i}: no valid reading (sensor not responding).", file=sys.stderr)
            else:
                print(f"Cycle {i}: {distance_m:.3f} m")

            if i < CYCLES and _running:
                time.sleep(DELAY_SECONDS)
    finally:
        try:
            sensor.close()
        except Exception:
            pass

if __name__ == "__main__":
    main()

