import serial
import sys
import signal

SERIAL_PORT = '/dev/serial0'  # Raspberry Pi primary UART (GPIO 14/15)
BAUD_RATE = 115200
TIMEOUT_S = 1.0
READ_RETRIES = 3

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def open_serial_port():
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT_S,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"Error: OS-level failure opening {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None
    return ser

def read_from_device(ser):
    try:
        ser.reset_input_buffer()
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Error: serial read failed: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None
    return raw.decode('ascii', errors='replace').strip()

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = open_serial_port()
    if ser is None:
        sys.exit(1)

    try:
        for attempt in range(1, READ_RETRIES + 1):
            if not _running:
                print("Interrupted by user.", file=sys.stderr)
                return
            data = read_from_device(ser)
            if data:
                print(f"Received: {data}")
                return
            if attempt < READ_RETRIES:
                print(f"No data (attempt {attempt}/{READ_RETRIES}).", file=sys.stderr)
    finally:
        try:
            ser.close()
        except Exception:
            pass

    print("No data received from device.", file=sys.stderr)
    sys.exit(1)

if __name__ == '__main__':
    main()

