import sys
from gpiozero import PWMOutputDevice

PWM_PINS = [12, 20, 21]
INTERVAL = 0.03

running = True

def handle_signal(signum, frame):
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    pwm_devices = []
    try:
        for pin in PWM_PINS:
            try:
                dev = PWMOutputDevice(pin, frequency=1000)
                dev.value = 0.0
                pwm_devices.append(dev)
            except Exception as e:
                print(f"Error initializing PWM on GPIO {pin}: {e}", file=sys.stderr)
                return 1

        while running:
            for dev in pwm_devices:
                dev.value = 0.5
            time.sleep(INTERVAL)
            if not running:
                break
            for dev in pwm_devices:
                dev.value = 0.0
            time.sleep(INTERVAL)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        return 1
    finally:
        for dev in pwm_devices:
            try:
                dev.value = 0.0
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

    return 0

