WHO_AM_I = 0x75
WHO_AM_I_EXPECTED = 0x68

running = True


def _handle_signal(signum, frame):
    global running
    running = False


def _write_reg(bus, addr, reg, value):
    bus.write_byte_data(addr, reg, value)


def _read_reg(bus, addr, reg):
    return bus.read_byte_data(addr, reg)


def _read_word(bus, addr, reg):
    return bus.read_word_data(addr, reg)


def _read_word_signed(bus, addr, reg):
    val = _read_word(bus, addr, reg)
    return val - 65536 if val >= 32768 else val


def _init_mpu6050(bus):
    who = _read_reg(bus, MPU6050_ADDR, WHO_AM_I)
    if who != WHO_AM_I_EXPECTED:
        raise RuntimeError(f"WHO_AM_I mismatch: got 0x{who:02X}, expected 0x{WHO_AM_I_EXPECTED:02X}")
    _write_reg(bus, MPU6050_ADDR, PWR_MGMT_1, 0x00)
    time.sleep(0.1)


def main():
    global running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = SMBus(1)
        _init_mpu6050(bus)

        print("MPU6050 initialized. Reading accelerometer/gyro data...")

        while running:
            try:
                accel_x = _read_word_signed(bus, MPU6050_ADDR, 0x3B)
                accel_y = _read_word_signed(bus, MPU6050_ADDR, 0x3D)
                accel_z = _read_word_signed(bus, MPU6050_ADDR, 0x3F)
                gyro_x = _read_word_signed(bus, MPU6050_ADDR, 0x43)
                gyro_y = _read_word_signed(bus, MPU6050_ADDR, 0x45)
                gyro_z = _read_word_signed(bus, MPU6050_ADDR, 0x47)

                print(
                    f"Accel (g): X={accel_x/100:.2f} Y={accel_y/100:.2f} Z={accel_z/100:.2f} "
                    f"Gyro (deg/s): X={gyro_x/65:.2f} Y={gyro_y/65:.2f} Z={gyro_z/65:.2f}"
                )
            except OSError as e:
                print(f"I2C read error: {e}", file=sys.stderr)
                return 1
            time.sleep(0.5)

    except OSError as e:
        print(f"Failed to open I2C bus or communicate with MPU6050 at 0x{MPU6050_ADDR:02X}: {e}", file=sys.stderr)
        return 1
    except RuntimeError as e:
        print(f"MPU6050 initialization error: {e}", file=sys.stderr)
        return 1
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass
        print("Program finished.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

