import time
import signal
import sys
import board
import adafruit_dht

# Pin definitions (BCM numbering)
DHT_PINS = [board.D4, board.D5, board.D17, board.D23]

# Global list to track initialized sensors for cleanup
sensors = []

def cleanup(signum=None, frame=None):
    """Release all DHT22 sensors on exit or signal."""
    for sensor in sensors:
        try:
            sensor.exit()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def main():
    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize DHT22 sensors
    for pin in DHT_PINS:
        try:
            sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
            sensors.append(sensor)
            print(f"Initialized DHT22 on pin {pin}")
        except Exception as e:
            print(f"Failed to initialize DHT22 on pin {pin}: {e}")
            continue

    if not sensors:
        print("No DHT22 sensors could be initialized. Exiting.")
        sys.exit(1)

    # Main loop: read and report every 60 seconds
    while True:
        for sensor in sensors:
            try:
                temperature = sensor.temperature
                humidity = sensor.humidity

                # Validate readings (DHT22 ranges: -40-80°C, 0-100%RH)
                if temperature is None or humidity is None:
                    print("Invalid reading: None value returned")
                    continue
                if not (-40.0 <= temperature <= 80.0):
                    print(f"Invalid reading: temperature {temperature} out of range")
                    continue
                if not (0.0 <= humidity <= 100.0):
                    print(f"Invalid reading: humidity {humidity} out of range")
                    continue

                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
            except RuntimeError as e:
                # DHT22 checksum or timing errors are common; skip this cycle
                print(f"Read error on this cycle: {e}")
            except Exception as e:
                print(f"Unexpected error reading sensor: {e}")

        time.sleep(60)

if __name__ == "__main__":
    main()

import time
import sys
import signal
import logging

import board
import busio
import digitalio
from adafruit_mcp3xxx import MCP3008

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("mcp3008_reader")

_running = True

def _handle_signal(signum, frame):
    global _running
    log.info("Signal %s received, shutting down...", signum)
    _running = False

def read_channel(adc, channel):
    """Return a valid 10-bit integer reading or None on error/timeout."""
    try:
        raw = adc.read(channel)
    except Exception as exc:
        log.error("ADC read failed on channel %d: %s", channel, exc)
        return None
    if raw is None:
        log.error("ADC returned None for channel %d", channel)
        return None
    if not isinstance(raw, int) or raw < 0 or raw > 1023:
        log.error("Invalid ADC value %r for channel %d", raw, channel)
        return None
    return raw

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    adc = None
    try:
        try:
            i2c = busio.I2C(board.SCL, board.SDA)
        except Exception as exc:
            log.error("Failed to initialize I2C bus: %s", exc)
            sys.exit(1)

        try:
            adc = MCP3008(i2c)
        except Exception as exc:
            log.error("MCP3008 not found on I2C bus: %s", exc)
            sys.exit(1)

        log.info("MCP3008 initialized; starting 3 readings (60 s apart).")

        for i in range(3):
            if not _running:
                log.info("Interrupted before reading %d.", i + 1)
                break

            log.info("Reading %d/3...", i + 1)
            value = read_channel(adc, 0)
            if value is not None:
                print(value)
            else:
                log.error("Skipping reading %d due to invalid data.", i + 1)

            if i < 2 and _running:
                time.sleep(60)

    except Exception as exc:
        log.exception("Unexpected error: %s", exc)
        sys.exit(1)
    finally:
        if adc is not None:
            try:
                adc.deinit()
            except Exception:
                pass
        log.info("Cleanup complete.")

if __name__ == "__main__":
    main()

