import time
import sys
import signal
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PINS = [17, 18, 27]
INTERVAL_SECONDS = 60

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    outputs = []
    try:
        for pin in PINS:
            try:
                outputs.append(OutputDevice(pin))
            except GPIOZeroError as exc:
                print(f"Error: failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
                for dev in outputs:
                    try:
                        dev.close()
                    except DeviceClosed:
                        pass
                sys.exit(1)
    except GPIOZeroError as exc:
        print(f"Error: GPIO subsystem unavailable: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            for dev in outputs:
                try:
                    dev.on()
                    print(f"GPIO {dev.pin.number} -> HIGH")
                except DeviceClosed:
                    print("Error: device closed unexpectedly.", file=sys.stderr)
                    break
            for dev in outputs:
                try:
                    dev.off()
                    print(f"GPIO {dev.pin.number} -> LOW")
                except DeviceClosed:
                    print("Error: device closed unexpectedly.", file=sys.stderr)
                    break
            for _ in range(INTERVAL_SECONDS):
                if not _running:
                    break
                time.sleep(1)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        for dev in outputs:
            try:
                dev.close()
            except DeviceClosed:
                pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

import time
import signal
import sys
from gpiozero import OutputDevice, DigitalInputDevice

TRIGGER_PINS = [17, 18, 22, 23]
ECHO_PINS = [17, 18, 22, 23]

running = True

def handle_signal(signum, frame):
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    triggers = []
    echoes = []
    try:
        for pin in TRIGGER_PINS:
            triggers.append(OutputDevice(pin))
            echoes.append(DigitalInputDevice(pin))
        time.sleep(0.1)
    except Exception as e:
        print(f"Failed to initialize GPIO: {e}", file=sys.stderr)
        for dev in triggers + echoes:
            dev.close()
        sys.exit(1)

    try:
        while running:
            for i in range(len(TRIGGER_PINS)):
                try:
                    triggers[i].on()
                    time.sleep(0.00001)
                    triggers[i].off()

                    timeout = time.time() + 0.03
                    while echoes[i].value == 0:
                        if time.time() > timeout:
                            print(f"HC-SR04 (pin {TRIGGER_PINS[i]}) timeout - no echo", file=sys.stderr)
                            break
                        time.sleep(0.0001)

                    if echoes[i].value == 1:
                        start = time.time()
                        timeout = start + 0.03
                        while echoes[i].value == 1:
                            if time.time() > timeout:
                                print(f"HC-SR04 (pin {TRIGGER_PINS[i]}) timeout - echo stuck high", file=sys.stderr)
                                break
                            time.sleep(0.0001)
                        elapsed = time.time() - start
                        distance = elapsed * 17150
                        print(f"HC-SR04 (pin {TRIGGER_PINS[i]}) Distance: {distance:.2f} cm")
                except Exception as e:
                    print(f"HC-SR04 (pin {TRIGGER_PINS[i]}) error: {e}", file=sys.stderr)
            for _ in range(5):
                if not running:
                    break
                time.sleep(1)
    finally:
        for dev in triggers + echoes:
            dev.close()
        print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

