import time
import signal
import sys
from gpiozero import DistanceSensor

TRIG_PIN = 14
ECHO_PIN = 24
MAX_RETRIES = 3
RETRY_DELAY = 0.1
LOOP_DELAY = 1.0

running = True

def handle_signal(signum, frame):
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        sensor = DistanceSensor(echo=ECHO_PIN, trigger=TRIG_PIN, max_distance=4.0)
    except Exception as e:
        print(f"Failed to initialize HC-SR04: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            for attempt in range(MAX_RETRIES):
                if not running:
                    break
                try:
                    distance = sensor.distance
                    if distance is not None:
                        print(f"Distance: {distance:.2f} m")
                        break
                except Exception as e:
                    print(f"Read error (attempt {attempt + 1}/{MAX_RETRIES}): {e}", file=sys.stderr)
                if attempt < MAX_RETRIES - 1:
                    time.sleep(RETRY_DELAY)
            else:
                print("HC-SR04 not responding after retries.", file=sys.stderr)
            if running:
                time.sleep(LOOP_DELAY)
    finally:
        sensor.close()
        print("GPIO cleanup done.")

if __name__ == "__main__":
    main()

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
BME280_ADDR = 0x29
REG_ID = 0xD0
REG_RESET = 0xE0
REG_CTRL_HUM = 0xF2
REG_STATUS = 0xF3
REG_CTRL_MEAS = 0xF4
REG_DATA = 0xF7

running = True


def _signal_handler(signum, frame):
    global running
    running = False


def _write_reg(bus, reg, value):
    bus.write_byte_data(BME280_ADDR, reg, value)


def _read_reg(bus, reg):
    return bus.read_byte_data(BME280_ADDR, reg)


def _read_block(bus, reg, length):
    return list(bus.read_i2c_block_data(BME280_ADDR, reg, length))


def _read_signed_16(bus, reg):
    data = _read_block(bus, reg, 2)
    return data[0] | (data[1] << 8)


def _read_signed_16_le(bus, reg):
    data = _read_block(bus, reg, 2)
    return data[0] | (data[1] << 8)


def _read_u16_le(bus, reg):
    data = _read_block(bus, reg, 2)
    return data[0] | (data[1] << 8)


def _read_u16_le_signed(bus, reg):
    val = _read_u16_le(bus, reg)
    return val - 65536 if val >= 32768 else val


def _read_u8(bus, reg):
    return _read_reg(bus, reg)


def _read_signed_8(bus, reg):
    val = _read_reg(bus, reg)
    return val - 256 if val >= 128 else val


def _read_temperature(bus):
    data = _read_block(bus, REG_DATA, 6)
    raw = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
    return raw / 100.0


def _read_pressure(bus):
    data = _read_block(bus, REG_DATA, 6)
    raw = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4)
    return raw / 25600.0


def _read_humidity(bus):
    data = _read_block(bus, REG_DATA, 6)
    raw = (data[3] << 8) | data[4]
    return raw / 1024.0


def main():
    global running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            chip_id = _read_reg(bus, REG_ID)
        except OSError as e:
            print(f"Error: no BME280 detected at 0x{BME280_ADDR:02X} on bus {I2C_BUS}: {e}", file=sys.stderr)
            sys.exit(1)

        if chip_id != 0x60:
            print(f"Error: unexpected chip ID 0x{chip_id:02X} (expected 0x60)", file=sys.stderr)
            sys.exit(1)

        _write_reg(bus, REG_RESET, 0xB6)
        time.sleep(0.01)

        _write_reg(bus, REG_CTRL_HUM, 0x01)
        _write_reg(bus, REG_CTRL_MEAS, 0x24)

        while running:
            try:
                temp = _read_temperature(bus)
                press = _read_pressure(bus)
                hum = _read_humidity(bus)
                print(f"T={temp:.2f} C  P={press:.2f} hPa  H={hum:.2f} %")
            except OSError as e:
                print(f"Warning: I2C read error: {e}", file=sys.stderr)
            time.sleep(2.0)
    finally:
        bus.close()


if __name__ == "__main__":
    main()

