import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'  # Raspberry Pi primary UART (GPIO 14/15)
BAUD_RATE = 9600
READ_TIMEOUT_S = 1.0
LOOP_INTERVAL_S = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _open_serial():
    try:
        return serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT_S,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"Error: OS-level failure opening {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None

def _read_once(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Warning: serial read error: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None
    return raw.decode('ascii', errors='replace').strip()

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = _open_serial()
    if ser is None:
        sys.exit(1)

    try:
        while _running:
            reading = _read_once(ser)
            if reading is not None and reading != '':
                print(f"Received: {reading}")
            else:
                print("No valid data received (timeout or error).")
            time.sleep(LOOP_INTERVAL_S)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        print("Serial port closed. Exiting.")

if __name__ == '__main__':
    main()

import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'  # Raspberry Pi primary UART (GPIO 14/15)
BAUD_RATE = 9600
READ_TIMEOUT_S = 1.0
LOOP_DELAY_S = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _cleanup(ser):
    if ser is not None and ser.is_open:
        try:
            ser.close()
        except Exception:
            pass

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = None
    try:
        try:
            ser = serial.Serial(
                port=SERIAL_PORT,
                baudrate=BAUD_RATE,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=READ_TIMEOUT_S,
            )
        except serial.SerialException as exc:
            print(f"Error: cannot open {SERIAL_PORT}: {exc}", file=sys.stderr)
            return 1

        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Error: serial read failed: {exc}", file=sys.stderr)
                return 1

            if not raw:
                print("Warning: no data received (timeout) - device may be absent", file=sys.stderr)
                continue

            data = raw.decode('ascii', errors='replace').strip()
            if not data:
                continue

            try:
                value = float(data)
            except ValueError:
                print(f"Warning: invalid data received: {data!r}", file=sys.stderr)
                continue

            if not (0 <= value <= 100):
                print(f"Warning: value {value} out of range [0, 100]", file=sys.stderr)
                continue

            print(f"Sensor Value: {value}")
            time.sleep(LOOP_DELAY_S)

    finally:
        _cleanup(ser)
    return 0

if __name__ == '__main__':
    sys.exit(main())

