import signal

SERIAL_PORT = '/dev/serial0'  # Raspberry Pi primary UART (GPIO 14/15)
BAUD_RATE = 9600
READ_TIMEOUT_S = 1.0
MAX_RETRIES = 3

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def open_serial_port():
    try:
        return serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT_S,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"Error: OS-level failure opening {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None

def read_valid_data(ser):
    for attempt in range(1, MAX_RETRIES + 1):
        if not _running:
            return None
        try:
            raw = ser.readline()
        except serial.SerialException as exc:
            print(f"Read error (attempt {attempt}/{MAX_RETRIES}): {exc}", file=sys.stderr)
            if attempt < MAX_RETRIES:
                continue
            return None
        if not raw:
            print("Warning: no data received (timeout).", file=sys.stderr)
            if attempt < MAX_RETRIES:
                continue
            return None
        data = raw.decode('ascii', errors='replace').strip()
        if not data:
            continue
        try:
            value = float(data)
        except ValueError:
            print(f"Invalid data (not a float): {data!r}", file=sys.stderr)
            continue
        if 0.0 <= value <= 100.0:
            return value
        print(f"Value out of range [0, 100]: {value}", file=sys.stderr)
    return None

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = open_serial_port()
    if ser is None:
        sys.exit(1)

    try:
        reading = read_valid_data(ser)
        if reading is not None:
            print(f"Sensor reading: {reading}")
        else:
            print("No valid reading received.", file=sys.stderr)
            sys.exit(1)
    finally:
        try:
            ser.close()
        except Exception:
            pass

if __name__ == '__main__':
    main()

