import time
import signal
import sys
import board
import adafruit_dht

DHT_PIN = board.D4
READ_INTERVAL = 5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialize DHT22 on {DHT_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                temperature = sensor.temperature
                humidity = sensor.humidity

                if temperature is None or humidity is None:
                    print("Error: sensor returned None", file=sys.stderr)
                elif not (-40 <= temperature <= 80):
                    print(f"Error: temperature out of range: {temperature}", file=sys.stderr)
                elif not (0 <= humidity <= 100):
                    print(f"Error: humidity out of range: {humidity}", file=sys.stderr)
                else:
                    print(f"Temperature: {temperature:.1f} C  Humidity: {humidity:.1f} %")

            except RuntimeError as exc:
                print(f"Read error: {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Unexpected error: {exc}", file=sys.stderr)

            for _ in range(READ_INTERVAL):
                if not _running:
                    break
                time.sleep(1)
    finally:
        try:
            sensor.exit()
        except Exception:
            pass

if __name__ == "__main__":
    main()

import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'  # Raspberry Pi primary UART (GPIO 14/15)
BAUD_RATE = 9600
READ_TIMEOUT = 0.05  # seconds between readings

# Graceful shutdown flag
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def main():
    global _running

    # Install signal handlers for clean exit on Ctrl-C / SIGTERM
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Open the serial port; exit non-zero if the device is absent
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT,
            write_timeout=READ_TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {SERIAL_PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Error: serial read failed: {exc}", file=sys.stderr)
                break

            if raw:
                text = raw.decode('ascii', errors='replace').strip()
                if text:
                    print(text)

            # Sleep in small increments so signals are caught promptly
            elapsed = 0.0
            while _running and elapsed < READ_TIMEOUT:
                time.sleep(0.005)
                elapsed += 0.005

    finally:
        # Release the serial port on every exit path
        try:
            if ser.is_open:
                ser.close()
        except Exception:
            pass

if __name__ == '__main__':
    main()

import signal
import sys
import time

from w1thermsensor import W1ThermSensor, SensorNotReadyError, NoSensorFoundError

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_temperature():
    """
    Reads the temperature from a DS18B20 sensor and prints it to the console.
    Handles potential errors and ensures clean resource release.
    """
    global _running
    _running = True

    sensor = None
    try:
        sensor = W1ThermSensor()
    except NoSensorFoundError:
        print("Error: DS18B20 sensor not found. Check 1-Wire connections.", file=sys.stderr)
        return
    except Exception as e:
        print(f"Error initializing sensor: {e}", file=sys.stderr)
        return

    try:
        if not _running:
            return

        temperature = sensor.get_temperature()
        if temperature is None or not isinstance(temperature, (int, float)):
            print("Error: Failed to retrieve valid temperature data.", file=sys.stderr)
            return

        print(f"Temperature: {temperature}°C")

    except SensorNotReadyError:
        print("Error: Sensor not ready. Check wiring and power.", file=sys.stderr)
    except Exception as e:
        print(f"Error reading temperature: {e}", file=sys.stderr)
    finally:
        if sensor is not None:
            try:
                sensor.close()
            except Exception:
                pass

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)
    read_temperature()

if __name__ == "__main__":
    main()

