import signal
import sys
import time
import board
import adafruit_dht

PINS = [board.D4, board.D7, board.D11, board.D17]
INTERVAL = 5.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    readings = []
    for pin in PINS:
        try:
            sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
            readings.append(sensor)
        except Exception as exc:
            print(f"Error: failed to initialize DHT22 on {pin}: {exc}", file=sys.stderr)
            readings.append(None)

    if None in readings:
        print("Error: one or more DHT22 devices are absent or unreachable.", file=sys.stderr)
        for idx, sensor in enumerate(readings):
            if sensor is None:
                print(f"  pin {PINS[idx]}")
        sys.exit(1)

    try:
        while _running:
            values = []
            for idx, sensor in enumerate(readings):
                try:
                    temp = sensor.temperature
                    hum = sensor.humidity
                    if temp is None or hum is None:
                        raise RuntimeError("sensor returned None")
                    values.append((temp, hum))
                except Exception as exc:
                    print(f"Warning: reading failed on pin {PINS[idx]}: {exc}", file=sys.stderr)
                    values.append(None)

            if all(v is None for v in values):
                print("Warning: no valid readings from any sensor.", file=sys.stderr)
            else:
                for temp, hum in values:
                    if temp is not None and hum is not None:
                        print(f"State: {temp:.1f}C, {hum:.1f}%")
                    else:
                        print("State: invalid reading", file=sys.stderr)

            for _ in range(int(INTERVAL * 10)):
                if not _running:
                    break
                time.sleep(0.1)
    finally:
        for sensor in readings:
            try:
                sensor.exit()
            except Exception:
                pass

if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PINS = [4, 5, 6, 13, 17, 22, 27]
DELAY = 0.01

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            try:
                dev = OutputDevice(pin)
                devices.append(dev)
            except GPIOZeroError as exc:
                print(f"Failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
                return 1

        while _running:
            for dev in devices:
                try:
                    dev.on()
                    print(f"GPIO {dev.pin.number} -> HIGH")
                except DeviceClosed:
                    print(f"GPIO {dev.pin.number} already closed", file=sys.stderr)
                except GPIOZeroError as exc:
                    print(f"GPIO {dev.pin.number} write error: {exc}", file=sys.stderr)
                    return 1
                time.sleep(DELAY)
                try:
                    dev.off()
                    print(f"GPIO {dev.pin.number} -> LOW")
                except DeviceClosed:
                    print(f"GPIO {dev.pin.number} already closed", file=sys.stderr)
                    return 1
                except GPIOZeroError as exc:
                    print(f"GPIO {dev.pin.number} write error: {exc}", file=sys.stderr)
                    return 1
                time.sleep(DELAY)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        return 1
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup complete.")
    return 0

if __name__ == "__main__":
    sys.exit(main())

