import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
WHO_AM_I = 0x75
WHO_AM_I_EXPECTED = 0x68

running = True


def _handle_signal(signum, frame):
    global running
    running = False


def _write_reg(bus, reg, value):
    bus.write_byte_data(MPU6050_ADDR, reg, value)


def _read_reg(bus, reg):
    return bus.read_byte_data(MPU6050_ADDR, reg)


def _read_word(bus, reg):
    low = bus.read_byte_data(MPU6050_ADDR, reg)
    high = bus.read_byte_data(MPU6050_ADDR, reg + 1)
    return (high << 8) | low


def _init_device(bus):
    who = _read_reg(bus, WHO_AM_I)
    if who != WHO_AM_I_EXPECTED:
        raise RuntimeError(f"WHO_AM_I mismatch: got 0x{who:02X}, expected 0x{WHO_AM_I_EXPECTED:02X}")
    _write_reg(bus, PWR_MGMT_1, 0x00)


def main():
    global running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = SMBus(1)
        _init_device(bus)
        print("MPU6050 initialized at address 0x68")

        while running:
            try:
                accel_x = _read_word(bus, 0x3B)
                accel_y = _read_word(bus, 0x3D)
                accel_z = _read_word(bus, 0x3F)
                print(f"Accel X={accel_x} Y={accel_y} Z={accel_z}")
            except OSError as e:
                print(f"I2C read error: {e}", file=sys.stderr)
                break
            time.sleep(0.1)

    except OSError as e:
        print(f"Failed to open I2C bus or communicate with MPU6050: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass
        print("Program terminated.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
TCS34725_ADDR = 0x29
REG_ENABLE = 0x80
REG_CONFIG = 0x81
REG_DATA0 = 0x82
REG_ID = 0x0F

ID_TCS34725 = 0x17

running = True


def _signal_handler(signum, frame):
    global running
    running = False


def _write_reg(bus, reg, value):
    bus.write_byte_data(TCS34725_ADDR, reg, value)


def _read_reg(bus, reg):
    return bus.read_byte_data(TCS34725_ADDR, reg)


def _read_rgb(bus):
    data = bus.read_i2c_block_data(TCS34725_ADDR, REG_DATA0, 4)
    r = (data[1] << 8) | data[0]
    g = (data[3] << 8) | data[2]
    b = (data[5] << 8) | data[4]
    return r, g, b


def _read_id(bus):
    return _read_reg(bus, REG_ID)


def _init_sensor(bus):
    _write_reg(bus, REG_ENABLE, 0x00)
    _write_reg(bus, REG_CONFIG, 0x00)
    time.sleep(0.01)


def main():
    global running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            chip_id = _read_id(bus)
        except OSError as exc:
            print(f"Error: no device at 0x{TCS34725_ADDR:02X} on bus {I2C_BUS}: {exc}", file=sys.stderr)
            sys.exit(1)

        if chip_id != ID_TCS34725:
            print(f"Error: unexpected TCS34725 ID 0x{chip_id:02X} (expected 0x17)", file=sys.stderr)
            sys.exit(1)

        _init_sensor(bus)

        while running:
            try:
                r, g, b = _read_rgb(bus)
            except OSError as exc:
                print(f"Warning: I2C read failed: {exc}", file=sys.stderr)
                time.sleep(0.01)
                continue

            if not (0 <= r <= 255 and 0 <= g <= 255 and 0 <= b <= 255):
                print(f"Warning: out-of-range RGB values ({r}, {g}, {b})", file=sys.stderr)
                time.sleep(0.01)
                continue

            print(f"R={r} G={g} B={b}")
            time.sleep(0.01)

    finally:
        try:
            _write_reg(bus, REG_ENABLE, 0x00)
        except OSError:
            pass
        bus.close()


if __name__ == "__main__":
    main()

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

PCF8574_ADDR = 0x27
I2C_BUS = 1
READ_INTERVAL = 2.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_pcf8574(bus, address):
    """Read a single byte from the PCF8574 and return it, or None on error."""
    try:
        write_msg = i2c_msg.write(address, [0x00])
        read_msg = i2c_msg.read(address, 1)
        bus.i2c_rdwr(write_msg, read_msg)
        return list(read_msg)[0]
    except OSError:
        return None
    except Exception:
        return None


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            reading = read_pcf8574(bus, PCF8574_ADDR)
            if reading is None:
                print("Error: failed to read from PCF8574 (device may be absent).", file=sys.stderr)
            else:
                print(f"PCF8574 reading: {reading}")
            time.sleep(READ_INTERVAL)
    finally:
        if bus is not None:
            bus.close()
        print("Program terminated.")


if __name__ == "__main__":
    main()

