import time
import sys
import signal
import logging

import board
import busio
import digitalio
from adafruit_mcp3xxx import MCP3008

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("mcp3008_reader")

_running = True

def _handle_signal(signum, frame):
    global _running
    log.info("Signal %s received, shutting down...", signum)
    _running = False

def read_adc(channel: int) -> int | None:
    """Read a single-ended channel from the MCP3008.

    Returns the 10-bit value (0-1023) or None on error / invalid reading.
    """
    try:
        adc = MCP3008(spi, cs)
    except Exception as exc:
        log.error("Failed to initialise MCP3008: %s", exc)
        return None

    try:
        value = adc.read(channel)
    except Exception as exc:
        log.error("MCP3008 read error on channel %d: %s", channel, exc)
        return None

    if value is None or not (0 <= value <= 1023):
        log.warning("Invalid ADC reading: %r", value)
        return None

    return value

def main() -> int:
    global spi, cs

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        spi = busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO)
        cs = digitalio.DigitalInOut(board.D5)
        cs.direction = digitalio.Direction.OUTPUT
        cs.value = True
    except Exception as exc:
        log.error("SPI / CS initialisation failed: %s", exc)
        return 1

    try:
        for i in range(5):
            if not _running:
                break
            value = read_adc(0)
            if value is not None:
                print(value)
            else:
                log.warning("Skipping reading %d due to error.", i + 1)
            if i < 4 and _running:
                time.sleep(300)
    finally:
        try:
            cs.deinit()
        except Exception:
            pass
        try:
            spi.deinit()
        except Exception:
            pass
        log.info("Resources released.")

    return 0 if _running else 130

if __name__ == "__main__":
    sys.exit(main())

import time
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIODeviceError, GPIODeviceClosed

PIN_1 = 17
PIN_2 = 27
INTERVAL = 0.2

def main():
    try:
        out1 = OutputDevice(PIN_1)
        out2 = OutputDevice(PIN_2)
    except GPIODeviceError as exc:
        print(f"Failed to initialize GPIO pins: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error during GPIO init: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            out1.on()
            out2.on()
