            print("Pin 17: LOW, Pin 27: LOW")
            time.sleep(INTERVAL)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    except Exception as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
    finally:
        try:
            out1.close()
        except GPIODeviceClosed:
            pass
        try:
