import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
BME280_ADDR = 0x76
READ_INTERVAL_S = 2
NUM_READINGS = 10

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _write_reg(bus, addr, reg, value):
    bus.write_byte_data(addr, reg, value & 0xFF)

def _read_reg(bus, addr, reg):
    return bus.read_byte_data(addr, reg)

def _read_u16le(bus, addr, reg):
    data = bus.read_i2c_block_data(addr, reg, 2)
    return data[0] | (data[1] << 8)

def _read_temp_hum(bus, addr):
    """Read temperature and humidity from the BME280."""
    # Trigger a forced measurement (ctrl_meas = 0x25, osrs_t=1, osrs_p=0, osrs_h=1)
    _write_reg(bus, addr, 0xF4, 0x25)
    time.sleep(0.01)
    # Read 8 bytes: press, temp, temp, press, hum, hum, hum, hum
    data = bus.read_i2c_block_data(addr, 0xF7, 8)
    press = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
    temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4)
    hum = (data[6] << 8) | data[7]
    return temp, hum

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        # Probe the device with a zero-length write to confirm it is present.
        try:
            bus.write_quick(BME280_ADDR)
        except OSError:
            print(f"Error: no BME280 found at address 0x{BME280_ADDR:02X} on bus {I2C_BUS}.", file=sys.stderr)
            sys.exit(1)

        for i in range(NUM_READINGS):
            if not _running:
                break
            try:
                temp, hum = _read_temp_hum(bus, BME280_ADDR)
                print(f"reading {i + 1}/{NUM_READINGS}: temp={temp}C, hum={hum}%")
            except OSError as exc:
                print(f"Error reading BME280: {exc}", file=sys.stderr)
                sys.exit(1)
            time.sleep(READ_INTERVAL_S)
    finally:
        bus.close()

if __name__ == "__main__":
    main()

