import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
TCS34725_ADDR = 0x29
REG_ENABLE = 0x80
REG_CONFIG = 0x81
REG_DATA0 = 0x82
REG_ID = 0x80

ID_TCS34725 = 0x17

running = True


def _signal_handler(signum, frame):
    global running
    running = False


def _write_reg(bus, reg, value):
    bus.write_byte_data(TCS34725_ADDR, reg, value)


def _read_reg(bus, reg):
    return bus.read_byte_data(TCS34725_ADDR, reg)


def _read_data(bus):
    data = bus.read_i2c_block_data(TCS34725_ADDR, REG_DATA0, 4)
    return (data[0] << 16) | (data[1] << 8) | data[2], data[3]


def _init_device(bus):
    if _read_reg(bus, REG_ID) != ID_TCS34725:
        raise RuntimeError(f"TCS34725 not found at 0x{TCS34725_ADDR:02X} (id=0x{_read_reg(bus, REG_ID):02X})")
    _write_reg(bus, REG_ENABLE, 0x00)
    _write_reg(bus, REG_CONFIG, 0x00)


def main():
    global running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            _init_device(bus)
        except OSError as exc:
            print(f"Error: TCS34725 not responding on bus {I2C_BUS}: {exc}", file=sys.stderr)
            sys.exit(1)

        while running:
            try:
                raw, _ = _read_data(bus)
            except OSError as exc:
                print(f"Warning: I2C read failed: {exc}", file=sys.stderr)
                time.sleep(1)
                continue

            if raw == 0:
                print("Warning: zero-length reading, skipping", file=sys.stderr)
                time.sleep(1)
                continue

            print(f"Color: {raw}")
            time.sleep(1)
    finally:
        try:
            bus.close()
        except OSError:
            pass


if __name__ == "__main__":
    main()

