import time
import signal
import sys
import board
import adafruit_dht

# Pin definitions (BCM numbering)
DHT22_PINS = [board.D4, board.D17, board.D27]

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def main():
    global _running

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize DHT22 sensors
    sensors = []
    for pin in DHT22_PINS:
        try:
            sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
            sensors.append(sensor)
        except Exception as e:
            print(f"Error initializing DHT22 on pin {pin}: {e}", file=sys.stderr)
            sensors.append(None)

    if not sensors:
        print("No DHT22 sensors initialized. Exiting.", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            for i, sensor in enumerate(sensors):
                if sensor is None:
                    continue
                try:
                    temperature = sensor.temperature
                    humidity = sensor.humidity
                    if temperature is not None and humidity is not None:
                        print(f"DHT22 {i+1}: Temperature = {temperature:.1f} C, Humidity = {humidity:.1f} %")
                    else:
                        print(f"DHT22 {i+1}: No data received (sensor may be absent or not ready)")
                except RuntimeError as e:
                    # DHT22 often throws transient read errors; log and continue
                    print(f"DHT22 {i+1}: Read error: {e}", file=sys.stderr)
                except Exception as e:
                    print(f"DHT22 {i+1}: Unexpected error: {e}", file=sys.stderr)

            # Sleep in small increments to allow prompt signal handling
            for _ in range(10):
                if not _running:
                    break
                time.sleep(0.1)

    finally:
        # Clean up: release GPIO resources
        for sensor in sensors:
            if sensor is not None:
                try:
                    sensor.exit()
                except Exception:
                    pass
        print("Program terminated. GPIO resources released.")

