import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
BME280_ADDR = 0x76
READ_INTERVAL_S = 60

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _write_reg(bus, reg, value):
    bus.write_byte_data(BME280_ADDR, reg, value & 0xFF)


def _read_reg(bus, reg):
    return bus.read_byte_data(BME280_ADDR, reg)


def _read_u16le(bus, reg):
    data = bus.read_i2c_block_data(BME280_ADDR, reg, 2)
    return data[0] | (data[1] << 8)


def _read_s16le(bus, reg):
    val = _read_u16le(bus, reg)
    return val - 65536 if val >= 32768 else val


def _read_raw_t(bus):
    data = bus.read_i2c_block_data(BME280_ADDR, 0xFA, 3)
    return (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)


def _read_raw_p(bus):
    data = bus.read_i2c_block_data(BME280_ADDR, 0xF7, 3)
    return (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)


def _read_raw_h(bus):
    data = bus.read_i2c_block_data(BME280_ADDR, 0xF7, 2)
    return (data[0] << 8) | data[1]


def _read_temperature(bus):
    raw = _read_raw_t(bus)
    return raw * 200.0 / 1048576.0 - 500.0


def _read_pressure(bus):
    raw = _read_raw_p(bus)
    return raw * 250.0 / 1048576.0


def _read_humidity(bus):
    raw = _read_raw_h(bus)
    h = raw * 100.0 / 1024.0
    if h < 0:
        h = 0.0
    elif h > 100.0:
        h = 100.0
    return h


def _init_bme280(bus):
    _write_reg(bus, 0xD4, 0x27)  # ctrl_meas: 1x, 1x, 1x
    _write_reg(bus, 0xF4, 0x34)  # config: 1x, 1x, 1x
    _write_reg(bus, 0xF5, 0x2F)  # standby: 0.5ms
    _write_reg(bus, 0xF6, 0x00)  # filter: off
    return True


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        if not _init_bme280(bus):
            print("Error: BME280 not responding at 0x76 on bus 1", file=sys.stderr)
            sys.exit(1)
    except OSError as exc:
        print(f"Error: BME280 init failed: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                temp = _read_temperature(bus)
                pres = _read_pressure(bus)
                hum = _read_humidity(bus)
                print(f"T={temp:.2f} C  P={pres:.2f} hPa  H={hum:.2f} %")
            except OSError as exc:
                print(f"Warning: I2C read error: {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Warning: unexpected read error: {exc}", file=sys.stderr)

            if _running:
                time.sleep(READ_INTERVAL_S)
    finally:
        bus.close()
        print("I2C bus released.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
WHO_AM_I = 0x75
WHO_AM_I_EXPECTED = 0x68

running = True


def _handle_signal(signum, frame):
    global running
    running = False


def _write_reg(bus, reg, value):
    bus.write_byte_data(MPU6050_ADDR, reg, value)


def _read_reg(bus, reg):
    return bus.read_byte_data(MPU6050_ADDR, reg)


def _read_word(bus, reg):
    low = bus.read_byte_data(MPU6050_ADDR, reg)
    high = bus.read_byte_data(MPU6050_ADDR, reg + 1)
    return (high << 8) | low


def _init_device(bus):
    who = _read_reg(bus, WHO_AM_I)
    if who != WHO_AM_I_EXPECTED:
        raise RuntimeError(f"WHO_AM_I mismatch: got 0x{who:02X}, expected 0x{WHO_AM_I_EXPECTED:02X}")
    _write_reg(bus, PWR_MGMT_1, 0x00)
    time.sleep(0.1)


def main():
    global running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = SMBus(1)
        _init_device(bus)

        for i in range(5):
            if not running:
                break
            try:
                who = _read_reg(bus, WHO_AM_I)
                print(f"Reading {i + 1}/5: WHO_AM_I=0x{who:02X}")
            except OSError as exc:
                print(f"Error reading MPU6050: {exc}", file=sys.stderr)
                return 1
            time.sleep(0.1)

        return 0
    except OSError as exc:
        print(f"Failed to open I2C bus: {exc}", file=sys.stderr)
        return 1
    except RuntimeError as exc:
        print(f"MPU6050 initialization error: {exc}", file=sys.stderr)
        return 1
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass


if __name__ == "__main__":
    sys.exit(main())

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
BME680_ADDR = 0x77
READ_INTERVAL_S = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _write_cmd(bus, cmd, params):
    write = i2c_msg.write(BME680_ADDR, [cmd] + params)
    bus.i2c_rdwr(write)


def _read_reg(bus, reg):
    write = i2c_msg.write(BME680_ADDR, [reg])
    read = i2c_msg.read(BME680_ADDR, 1)
    bus.i2c_rdwr(write, read)
    return list(read)[0]


def _read_reg_block(bus, reg, length):
    write = i2c_msg.write(BME680_ADDR, [reg])
    read = i2c_msg.read(BME680_ADDR, length)
    bus.i2c_rdwr(write, read)
    return list(read)


def _read_sensor_data(bus):
    data = _read_reg_block(bus, 0x1A, 24)
    if len(data) < 24:
        raise IOError("short read from BME680")
    return {
        "temperature": int.from_bytes(data[0:2], "little", signed=True) / 100.0,
        "pressure": int.from_bytes(data[2:4], "little", signed=True) / 100.0,
        "humidity": int.from_bytes(data[4:6], "little", signed=True) / 1024.0,
    }


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        # Probe the device with a chip ID read.
        try:
            chip_id = _read_reg(bus, 0xD0)
        except OSError as exc:
            print(f"Error: no BME680 detected at 0x{BME680_ADDR:02X} on bus {I2C_BUS}: {exc}", file=sys.stderr)
            sys.exit(1)

        if chip_id != 0x61:
            print(f"Error: unexpected chip ID 0x{chip_id:02X} (expected 0x61)", file=sys.stderr)
            sys.exit(1)

        while _running:
            try:
                data = _read_sensor_data(bus)
                print(
                    f"Temp: {data['temperature']:.2f} C  "
                    f"Pressure: {data['pressure']:.2f} hPa  "
                    f"Humidity: {data['humidity']:.2f} %"
                )
            except IOError as exc:
                print(f"Warning: sensor read failed: {exc}", file=sys.stderr)
            time.sleep(READ_INTERVAL_S)
    finally:
        bus.close()


if __name__ == "__main__":
    main()

