import sys
import signal
import time

try:
    import board
    import busio
    from adafruit_mcp3xxx.mcp3008 import MCP3008
except ImportError as exc:
    print(f"Missing dependency: {exc}", file=sys.stderr)
    print("Install with: pip install adafruit-circuitpython-mcp3xxx", file=sys.stderr)
    sys.exit(1)

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_adc(channel: int) -> int | None:
    """Read a single-ended channel from the MCP3008.

    Returns the 10-bit value (0-1023) or None on a bad read.
    """
    try:
        adc = MCP3008(busio.I2C(), address=0x60)
    except Exception as exc:
        print(f"Failed to initialize MCP3008: {exc}", file=sys.stderr)
        return None

    try:
        value = adc.read_adc(channel)
    except Exception as exc:
        print(f"Error reading ADC channel {channel}: {exc}", file=sys.stderr)
        return None

    if value is None or not (0 <= value <= 1023):
        print(f"Invalid ADC reading: {value}", file=sys.stderr)
        return None

    return value

def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        value = read_adc(0)
        if value is not None:
            print(value)
        return 0
    finally:
        try:
            adc = MCP3008(busio.I2C(), address=0x60)
            adc.deinit()
        except Exception:
            pass

if __name__ == "__main__":
    sys.exit(main())

import signal
import sys
import smbus2

I2C_BUS = 1
PCA9685_ADDR = 0x40
REG_PRESCALE = 0xFE
REG_MODE1 = 0x00
MODE1_SLEEP = 0x10
MODE1_RESTART = 0x80
MODE1_ALLCALL = 0x01

running = True

def _signal_handler(signum, frame):
    global running
    running = False

def _write_reg(bus, addr, reg, value):
    bus.write_byte_data(addr, reg, value & 0xFF)

def _read_reg(bus, addr, reg):
    return bus.read_byte_data(addr, reg)

def _init_pca9685(bus, addr):
    _write_reg(bus, addr, REG_PRESCALE, 0x00)
    _write_reg(bus, addr, REG_MODE1, MODE1_SLEEP | MODE1_ALLCALL)
    _write_reg(bus, addr, REG_MODE1, MODE1_RESTART | MODE1_ALLCALL)

def main():
    global running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        _init_pca9685(bus, PCA9685_ADDR)
    except OSError as exc:
        print(f"Error: PCA9685 not found at 0x{PCA9685_ADDR:02X}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            try:
                mode1 = _read_reg(bus, PCA9685_ADDR, REG_MODE1)
                print(f"Mode1: 0x{mode1:02X}")
                print("All call enabled; sleeping 1 s before exit.")
                break
            except OSError as exc:
                print(f"Warning: I2C read failed: {exc}", file=sys.stderr)
                break
    finally:
        try:
            _write_reg(bus, PCA9685_ADDR, REG_MODE1, MODE1_SLEEP | MODE1_ALLCALL)
        except OSError:
            pass
        bus.close()
        print("PCA9685 put to sleep; resources released.")

if __name__ == "__main__":
    main()

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
I2C_ADDR = 0x76
READ_INTERVAL = 5.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _write_cmd(bus, cmd):
    write = i2c_msg.write(I2C_ADDR, [cmd])
    bus.i2c_rdwr(write)

def _read_raw(bus):
    write = i2c_msg.write(I2C_ADDR, [0xF7])
    read = i2c_msg.read(I2C_ADDR, 8)
    bus.i2c_rdwr(write, read)
    return list(read)

def _read_temperature(bus):
    _write_cmd(bus, 0xF6)
    time.sleep(0.005)
    data = _read_raw(bus)
    return (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)

def _read_pressure(bus):
    _write_cmd(bus, 0xF4)
    time.sleep(0.005)
    data = _read_raw(bus)
    raw = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
    if raw & 0x80000:
        raw -= 1 << 20
    return raw

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                temp = _read_temperature(bus)
                press = _read_pressure(bus)
                print(f"Temperature: {temp/100.0:.2f} C  Pressure: {press/25600.0:.2f} hPa")
            except OSError as exc:
                print(f"Warning: I2C read failed: {exc}", file=sys.stderr)
            time.sleep(READ_INTERVAL)
    finally:
        bus.close()

if __name__ == "__main__":
    main()

import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'  # Raspberry Pi primary UART (GPIO 14/15)
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
LOOP_DELAY = 0.1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def open_serial_port():
    try:
        return serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"Error: OS-level failure opening {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None

def read_valid_data(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Error: serial read failed: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None
    try:
        return raw.decode('ascii', errors='replace').strip()
    except Exception as exc:
        print(f"Error: failed to decode data: {exc}", file=sys.stderr)
        return None

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = open_serial_port()
    if ser is None:
        sys.exit(1)

    try:
        while _running:
            data = read_valid_data(ser)
            if data is not None and data != '':
                print(f"Received: {data}")
            time.sleep(LOOP_DELAY)
    finally:
        try:
            ser.close()
        except Exception:
            pass

if __name__ == '__main__':
    main()

import sys
import time
import signal
from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PWM_PIN = 17
MIN_PWM = 0.0
MAX_PWM = 100.0
UPDATE_INTERVAL = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        pwm = PWMOutputDevice(PWM_PIN, frequency=1000)
    except GPIOZeroError as exc:
        print(f"Error: failed to initialize PWM on GPIO {PWM_PIN}: {exc}", file=sys.stderr)
