import signal
from gpiozero import OutputDevice
from gpiozero.exc import GPIODeviceError, GPIOPinInUse

PIN = 18

def main() -> int:
    try:
        led = OutputDevice(PIN)
    except (GPIOPinInUse, GPIODeviceError) as exc:
        print(f"Error: unable to initialize GPIO {PIN}: {exc}", file=sys.stderr)
        return 1

    def cleanup() -> None:
        try:
            led.close()
        except Exception:
            pass

    def handle_signal(signum, frame) -> None:
        cleanup()
        sys.exit(0)

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        led.on()
        print(f"GPIO {PIN} set HIGH")
    except Exception as exc:
        print(f"Error: failed to write GPIO {PIN}: {exc}", file=sys.stderr)
        return 1
    finally:
        cleanup()
    return 0

if __name__ == "__main__":
    sys.exit(main())

import time
import signal
import sys
from w1thermsensor import W1ThermSensor, SensorNotReadyError, NoSensorFoundError

ONE_WIRE_PIN = 4
SAMPLE_INTERVAL = 5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = W1ThermSensor()
    except NoSensorFoundError:
        print("Error: No DS18B20 sensor found on the 1-Wire bus.", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error: Failed to initialize sensor: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                temperature = sensor.get_temperature()
                print(f"Temperature: {temperature:.2f} °C")
            except SensorNotReadyError:
                print("Warning: Sensor not ready, skipping reading.", file=sys.stderr)
            except Exception as e:
                print(f"Warning: Error reading temperature: {e}", file=sys.stderr)

            for _ in range(SAMPLE_INTERVAL):
                if not _running:
                    break
                time.sleep(1)
    finally:
        print("Exiting program.")

if __name__ == "__main__":
    main()

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
WHO_AM_I = 0x75
WHO_AM_I_EXPECTED = 0x68
ACCEL_XOUT_H = 0x3B

running = True


def _signal_handler(signum, frame):
    global running
    running = False


def _write_reg(bus, reg, value):
    bus.write_byte_data(MPU6050_ADDR, reg, value)


def _read_reg(bus, reg):
    return bus.read_byte_data(MPU6050_ADDR, reg)


def _read_word(bus, reg):
    high = bus.read_byte_data(MPU6050_ADDR, reg)
    low = bus.read_byte_data(MPU6050_ADDR, reg + 1)
    return (high << 8) | low


def _read_accel(bus):
    raw = _read_word(bus, ACCEL_XOUT_H)
    x = raw >> 8
    y = raw & 0xFF
    z = _read_word(bus, ACCEL_XOUT_H + 2)
    return x, y, z


def _validate(x, y, z):
    if not (-32768 <= x <= 32767 and -32768 <= y <= 32767 and -32768 <= z <= 32767):
        return False
    return True


def main():
    global running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = None
    try:
        bus = SMBus(1)
    except OSError as exc:
        print(f"Error: cannot open I2C bus 1: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            who = _read_reg(bus, WHO_AM_I)
        except OSError as exc:
            print(f"Error: MPU6050 not responding at 0x{MPU6050_ADDR:02X}: {exc}", file=sys.stderr)
            sys.exit(1)

        if who != WHO_AM_I_EXPECTED:
            print(f"Error: unexpected WHO_AM_I 0x{who:02X} (expected 0x{WHO_AM_I_EXPECTED:02X})", file=sys.stderr)
            sys.exit(1)

        _write_reg(bus, PWR_MGMT_1, 0x00)
        time.sleep(0.1)

        while running:
            try:
                x, y, z = _read_accel(bus)
            except OSError as exc:
                print(f"Error: I2C read failed: {exc}", file=sys.stderr)
                sys.exit(1)

            if not _validate(x, y, z):
                print("Error: out-of-range accelerometer reading", file=sys.stderr)
                sys.exit(1)

            print(f"Accel X: {x}, Accel Y: {y}, Accel Z: {z}")
            break

    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass


if __name__ == "__main__":
    main()

import time
import signal
import sys
from gpiozero import OutputDevice

PIN_1 = 17
PIN_2 = 18
INTERVAL = 0.1

running = True

def handle_signal(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)

try:
    out1 = OutputDevice(PIN_1)
    out2 = OutputDevice(PIN_2)
except Exception as e:
    print(f"Failed to initialize GPIO pins: {e}", file=sys.stderr)
    sys.exit(1)

try:
    while running:
        try:
            out1.on()
            out2.on()
            print("State: ON")
        except Exception as e:
            print(f"Error setting output: {e}", file=sys.stderr)
        time.sleep(INTERVAL)

        if not running:
            break

        try:
            out1.off()
            out2.off()
            print("State: OFF")
        except Exception as e:
            print(f"Error clearing output: {e}", file=sys.stderr)
        time.sleep(INTERVAL)
except Exception as e:
    print(f"Unexpected error: {e}", file=sys.stderr)
finally:
    try:
        out1.close()
    except Exception:
        pass
    try:
        out2.close()
    except Exception:
        pass
    print("GPIO cleanup completed.")

