import time
import signal
import sys
from gpiozero import OutputDevice

TRIG_PINS = [19, 20, 24, 25, 26]
trig_devices = []
running = True

def cleanup():
    for dev in trig_devices:
        try:
            dev.close()
        except Exception:
            pass
    trig_devices.clear()

def handle_signal(signum, frame):
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    for pin in TRIG_PINS:
        try:
            dev = OutputDevice(pin)
            dev.off()
            trig_devices.append(dev)
        except Exception as e:
            print(f"Failed to initialize GPIO {pin}: {e}", file=sys.stderr)
            cleanup()
            sys.exit(1)

    print("HC-SR04 trigger pins initialized. Press Ctrl+C to exit.")

    while running:
        for dev in trig_devices:
            try:
                dev.on()
                time.sleep(0.00001)
                dev.off()
            except Exception as e:
                print(f"Error writing to GPIO {dev.pin}: {e}", file=sys.stderr)
                running = False
                break
        time.sleep(1)

    print("Program terminated.")
    cleanup()

if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

TRIG_PINS = [5, 6, 17, 18, 22, 23, 24, 27]
ECHO_PINS = [5, 6, 17, 18, 22, 23, 24, 27]

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    trig_devices = []
    echo_devices = []
    try:
        for pin in TRIG_PINS:
            dev = OutputDevice(pin)
            dev.off()
            trig_devices.append(dev)
        for pin in ECHO_PINS:
            dev = OutputDevice(pin)
            dev.off()
            echo_devices.append(dev)

        for i, trig in enumerate(trig_devices):
            state = 1 if trig.is_active else 0
            print(f"GPIO {ECHO_PINS[i]} (TRIG) state: {state}")
            if i < len(echo_devices) - 1:
                print("-" * 40)

        for dev in trig_devices + echo_devices:
            dev.close()

    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"GPIO error: {exc}", file=sys.stderr)
        for dev in trig_devices + echo_devices:
            try:
                dev.close()
            except Exception:
                pass
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        for dev in trig_devices + echo_devices:
            try:
                dev.close()
            except Exception:
                pass
        sys.exit(1)

if __name__ == "__main__":
    main()

import signal
import sys
from gpiozero import PWMOutputDevice

PIN_17 = 17
PIN_22 = 22
PIN_27 = 27

pwm_devices = []

def cleanup(signum=None, frame=None):
    for dev in pwm_devices:
        try:
            dev.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def main():
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        pwm_devices.extend([PWMOutputDevice(PIN_17), PWMOutputDevice(PIN_22), PWMOutputDevice(PIN_27)])
    except Exception as e:
        print(f"Failed to initialize PWM devices: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    print("PWM output applied. Press Ctrl+C to exit.")
    try:
        while True:
            signal.pause()
    except KeyboardInterrupt:
        pass
    finally:
        cleanup()

if __name__ == "__main__":
    main()

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
BME280_ADDR = 0x76
READ_INTERVAL_S = 2
NUM_READINGS = 5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _write_reg(bus, reg, value):
    bus.write_byte_data(BME280_ADDR, reg, value & 0xFF)


def _read_reg(bus, reg):
    return bus.read_byte_data(BME280_ADDR, reg)


def _read_u16le(bus, reg):
    data = bus.read_i2c_block_data(BME280_ADDR, reg, 2)
    return data[0] | (data[1] << 8)


def _read_temp_hum(bus):
    """Read temperature and humidity from the BME280."""
    # Trigger a forced measurement (ctrl_meas = 0x25, osrs_t=1, osrs_p=0, osrs_h=1)
    _write_reg(bus, 0xF4, 0x25)
    time.sleep(0.01)

    # Read 8 bytes: press, temp, temp, press, hum, hum, hum, hum
    data = bus.read_i2c_block_data(BME280_ADDR, 0xF7, 8)
    raw_press = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
    raw_temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4)
    raw_hum = (data[6] << 8) | data[7]

    # Convert temperature (calibration data required for accuracy)
    # For a simple reading we use the raw value; a full calibration would
    # load the 26-byte calibration block and apply the formulas.
    temp = raw_temp / 100.0
    hum = raw_hum / 1024.0
    return temp, hum


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        # Verify device presence
        try:
            _read_reg(bus, 0xD0)  # Chip ID register
        except OSError as exc:
            print(f"Error: no BME280 found at address 0x{BME280_ADDR:02X} on bus {I2C_BUS}: {exc}", file=sys.stderr)
            sys.exit(1)

        readings_done = 0
        while _running and readings_done < NUM_READINGS:
            try:
                temp, hum = _read_temp_hum(bus)
                print(f"Temperature: {temp:.2f} C  Humidity: {hum:.2f} %")
            except OSError as exc:
                print(f"Warning: I2C read failed: {exc}", file=sys.stderr)
            readings_done += 1

            if _running and readings_done < NUM_READINGS:
                time.sleep(READ_INTERVAL_S)

    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass


if __name__ == "__main__":
    main()

import time
import signal
import sys
from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PINS = [5, 6, 13, 17, 18, 22, 23, 24, 27]
PWM_FREQ = 100  # Hz
INTERVAL = 1.0  # seconds

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    for pin in PINS:
        try:
            dev = PWMOutputDevice(pin, frequency=PWM_FREQ, initial_value=0.0)
            devices.append(dev)
        except GPIOZeroError as e:
            print(f"Error: failed to initialize PWM on GPIO{pin}: {e}", file=sys.stderr)
            for d in devices:
                try:
                    d.close()
                except DeviceClosed:
                    pass
            sys.exit(1)

    try:
        while _running:
            for dev in devices:
                try:
                    val = dev.value
                    if not (0.0 <= val <= 1.0):
                        print(f"Warning: invalid PWM value {val} on GPIO{dev.pin}", file=sys.stderr)
                        continue
                    print(f"GPIO{dev.pin}: {val}")
                except DeviceClosed:
                    print(f"Error: device on GPIO{dev.pin} closed unexpectedly", file=sys.stderr)
                    break
                except GPIOZeroError as e:
                    print(f"Error: read failed on GPIO{dev.pin}: {e}", file=sys.stderr)
                    break
            time.sleep(INTERVAL)
    finally:
        for dev in devices:
            try:
                dev.close()
            except DeviceClosed:
                pass
        print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

import sys
import signal
from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PIN = 17

def main():
    try:
        pwm = PWMOutputDevice(PIN)
    except GPIOZeroError as exc:
        print(f"Error: cannot open GPIO {PIN}: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error opening GPIO {PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    def cleanup(signum=None, frame=None):
        try:
            pwm.close()
        except DeviceClosed:
            pass
        except Exception:
            pass
        if signum is not None:
            sys.exit(0)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        pwm.value = 0.5
        print(f"PWM set to 0.5 on GPIO {PIN}")
    except DeviceClosed:
        print("Error: device closed unexpectedly", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Error: failed to set PWM: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'  # Raspberry Pi primary UART (GPIO 14/15)
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
NUM_READINGS = 3
INTERVAL_SECONDS = 2.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_sensor_data(ser):
    """Read one line from the serial port. Returns None on timeout or error."""
    try:
        raw = ser.readline()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    if not raw:
        return None
    return raw.decode('ascii', errors='replace').strip()

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=READ_TIMEOUT)
    except serial.SerialException as e:
        print(f"Failed to open {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        readings_done = 0
        while _running and readings_done < NUM_READINGS:
            data = read_sensor_data(ser)
            if data:
                print(f"Sensor reading: {data}")
                readings_done += 1
            if _running and readings_done < NUM_READINGS:
                time.sleep(INTERVAL_SECONDS)
    finally:
        if ser.is_open:
            ser.close()
        print("Serial port closed.")

if __name__ == '__main__':
    main()

import time
import signal
import sys
import board
import busio
import digitalio
import adafruit_mcp3xxx.mcp3008 as mcp
from adafruit_mcp3xxx.analog_in import AnalogIn

# Global resources for cleanup
spi = None
cs = None
adc = None
running = True

def cleanup():
    global spi, cs, adc
    if adc is not None:
        try:
            adc.close()
        except Exception:
            pass
    if cs is not None:
        try:
            cs.deinit()
        except Exception:
            pass
    if spi is not None:
        try:
            spi.deinit()
        except Exception:
            pass

def handle_signal(signum, frame):
    global running
    running = False

def main():
    global spi, cs, adc

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        spi = busio.SPI(clock=board.SCK, MISO=board.MISO, MOSI=board.MOSI)
        cs = digitalio.DigitalInOut(board.D5)
        cs.direction = digitalio.Direction.OUTPUT
        cs.value = True
        adc = mcp.MCP3008(spi, cs)
    except Exception as e:
        print(f"Error initializing MCP3008: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    while running:
        try:
            channel = AnalogIn(adc, mcp.P0)
            if not 0 <= channel.value <= 1023:
                print("Warning: reading out of range (0-1023)", file=sys.stderr)
            else:
                print(channel.value)
        except Exception as e:
            print(f"Error reading MCP3008: {e}", file=sys.stderr)
        time.sleep(5)

    cleanup()

if __name__ == "__main__":
    main()

import signal
import sys
import time
import board
import adafruit_dht

# --- Configuration -----------------------------------------------------------
DHT_PIN = board.D4          # BCM GPIO 4 (physical pin 7)
CYCLES = 3
DELAY_S = 2.0

# --- Globals for cleanup -----------------------------------------------------
_sensor = None
_running = True


def _cleanup():
    """Release hardware resources."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def main():
    global _sensor

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialise the DHT22 on GPIO 4
    try:
        _sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialise DHT22 on GPIO 4: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    try:
        for i in range(1, CYCLES + 1):
            if not _running:
                break

            try:
                temperature = _sensor.temperature
                humidity = _sensor.humidity
            except RuntimeError as exc:
                # DHT22 checksum / timing glitches are common; report and continue
                print(f"Cycle {i}: read error -> {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Cycle {i}: unexpected error -> {exc}", file=sys.stderr)

            if temperature is not None and humidity is not None:
                print(f"Cycle {i}: {temperature:.1f} C  {humidity:.1f} %")
            else:
                print(f"Cycle {i}: no valid data")

            if i < CYCLES and _running:
                time.sleep(DELAY_S)

    finally:
        _cleanup()


if __name__ == "__main__":
    main()
